   <div id="app"></div>

   <script>
     const fields = [
       {
         id: "full-name",
         name: "fullName",
         label: "Full name",
         type: "text",
         autocomplete: "name",
         required: true,
         error: "Error: Enter your full name."
       },
       {
         id: "email",
         name: "email",
         label: "Email address",
         type: "email",
         autocomplete: "email",
         required: true,
         error: "Error: Enter a valid email address, like name@example.com."
       },
       {
         id: "phone",
         name: "phone",
         label: "Phone number",
         type: "tel",
         autocomplete: "tel",
         required: false,
         help: "Use digits, spaces, parentheses, or dashes; for example, (555) 123-4567."
       }
     ];

     function escapeHtml(value) {
       return String(value).replace(/[&<>"']/g, (character) => ({
         "&": "&amp;",
         "<": "&lt;",
         ">": "&gt;",
         "\"": "&quot;",
         "'": "&#039;"
       })[character]);
     }

     function SupportPage() {
       return `
         <div class="page-shell">
           <main id="main-content">
             <section class="support-card" aria-labelledby="support-title">
               <div class="card-header">
                 <h1 id="support-title">Contact support</h1>
                 <p class="intro">Tell us how to reach you and our support team will follow up as soon as possible.</p>
               </div>
               ${ContactForm()}
             </section>
           </main>
         </div>
       `;
     }

     function ContactForm() {
       return `
         <form class="contact-form" id="contact-form" novalidate>
           <p class="required-note"><span class="required-marker" aria-hidden="true">*</span> indicates a required field.</p>
           ${fields.map(FormField).join("")}
           <button class="submit-button" type="submit">Send support request</button>
           <p class="form-status" id="form-status" aria-live="polite"></p>
         </form>
       `;
     }

     function FormField(field) {
       const requiredText = field.required ? ' <span class="required-marker" aria-hidden="true">*</span>' : " (optional)";
       const describedBy = [
         field.help ? `${field.id}-help` : "",
         field.required ? `${field.id}-error` : ""
       ].filter(Boolean).join(" ");

       return `
         <div class="form-field">
           <label for="${field.id}">${escapeHtml(field.label)}${requiredText}</label>
           <input
             id="${field.id}"
             name="${field.name}"
             type="${field.type}"
             autocomplete="${field.autocomplete}"
             ${field.required ? "required" : ""}
             ${describedBy ? `aria-describedby="${describedBy}"` : ""}
           >
           ${field.help ? `<p class="field-help" id="${field.id}-help">${escapeHtml(field.help)}</p>` : ""}
           ${field.required ? `<p class="field-error" id="${field.id}-error"></p>` : ""}
         </div>
       `;
     }

     function getFieldConfig(input) {
       return fields.find((field) => field.id === input.id);
     }

     function getValidationError(input) {
       const field = getFieldConfig(input);
       if (!field || !field.required) {
         return "";
       }

       if (input.validity.valueMissing) {
         return field.error;
       }

       if (input.validity.typeMismatch) {
         return field.error;
       }

       return "";
     }

     function setFieldError(input, message) {
       const errorElement = document.getElementById(`${input.id}-error`);
       if (!errorElement) {
         return;
       }

       errorElement.textContent = message;
       if (message) {
         input.setAttribute("aria-invalid", "true");
       } else {
         input.removeAttribute("aria-invalid");
       }
     }

     function setupContactForm() {
       const form = document.getElementById("contact-form");
       const status = document.getElementById("form-status");

       form.addEventListener("submit", (event) => {
         event.preventDefault();
         status.textContent = "";

         const inputs = Array.from(form.querySelectorAll("input"));
         let firstInvalidInput = null;

         inputs.forEach((input) => {
           const message = getValidationError(input);
           setFieldError(input, message);

           if (message && !firstInvalidInput) {
             firstInvalidInput = input;
           }
         });

         if (firstInvalidInput) {
           firstInvalidInput.focus();
           return;
         }

         status.textContent = "Your support request is ready to send.";
         form.reset();
       });

       form.addEventListener("input", (event) => {
         if (!(event.target instanceof HTMLInputElement)) {
           return;
         }

         if (event.target.getAttribute("aria-invalid") === "true") {
           setFieldError(event.target, getValidationError(event.target));
         }
       });
     }

     document.getElementById("app").innerHTML = SupportPage();
     setupContactForm();
   </script>
 </body>
 </html>

